def translate(text, lang='ar'):
    """ترجمة نص عربي إلى اللغة المطلوبة."""
    if not text:
        return ''
    text = str(text)
    if lang == 'ar' or lang not in I18N_DICT:
        return text
    return I18N_DICT[lang].get(text, text)

def get_direction(lang):
    """إرجاع اتجاه اللغة (rtl أو ltr)."""
    return SUPPORTED_LANGUAGES.get(lang, SUPPORTED_LANGUAGES['ar'])['dir']

def get_language_name(lang):
    """إرجاع اسم اللغة باللغة الأصلية."""
    return SUPPORTED_LANGUAGES.get(lang, SUPPORTED_LANGUAGES['ar'])['name']